<script setup lang="ts">
import {ref,watch,onBeforeUnmount,computed,nextTick} from 'vue'
import type {Snapshot,Conversation} from '../types'
import {accountConversations,accountRecordConversation,resolveAccountRecordTarget} from '../channel-management.mjs'
import {channelAccountName,channelConversationName,channelPlatformName} from '../../core/channel-display.mjs'
import ChannelConversationAvatar from '../components/ChannelConversationAvatar.vue'
import CharacterAvatar from '../components/CharacterAvatar.vue'
import MessageTimeline from '../components/MessageTimeline.vue'
import ToggleSwitch from '../components/ToggleSwitch.vue'
import {request,upload} from '../api'
import CustomSelect from '../components/CustomSelect.vue'
import Icon from '../components/Icon.vue'
import Modal from '../components/Modal.vue'
const props=withDefaults(defineProps<{state:Snapshot;active:boolean;refreshKey?:number;target?:{accountId?:string;conversationId?:string};displaySupported?:boolean;displayBusyIds?:string[];displayErrors?:Record<string,string>;displayDrafts?:Record<string,boolean>}>(),{refreshKey:0,displaySupported:false,displayBusyIds:()=>[],displayErrors:()=>({}),displayDrafts:()=>({})}),emit=defineEmits<{refresh:[];error:[unknown];notice:[string];'open-conversation':[id:string];'open-plugin':[id:string];display:[id:string,shown:boolean]}>()
const selectedAccountId=ref(''),recordId=ref(''),accountSearch=ref(''),recordSearch=ref(''),accountError=ref(''),accountsLoading=ref(false),detail=ref<HTMLElement>(),accountList=ref<HTMLElement>(),accountScroll=ref<HTMLElement>()
const accountScrollPositions=new Map<string,number>()
function rememberAccountScroll(){if(selectedAccountId.value&&accountScroll.value)accountScrollPositions.set(selectedAccountId.value,accountScroll.value.scrollTop)}
function restoreAccountScroll(){if(accountScroll.value)accountScroll.value.scrollTop=accountScrollPositions.get(selectedAccountId.value)??0}
const selectedAccount=computed(()=>connections.value.find(account=>account.accountId===selectedAccountId.value))
const selectedPlugin=computed(()=>plugins.value.find(plugin=>plugin.id===selectedAccount.value?.pluginId))
const visibleAccounts=computed(()=>{const term=accountSearch.value.trim().toLocaleLowerCase();return connections.value.filter(account=>!term||[accountName(account),plugins.value.find(plugin=>plugin.id===account.pluginId)?.name,props.state.characters.find(person=>person.id===account.characterId)?.name].some(value=>String(value??'').toLocaleLowerCase().includes(term)))})
const accountChats=computed<Conversation[]>(()=>accountConversations(props.state.conversations,selectedAccountId.value))
const visibleChats=computed(()=>{const term=recordSearch.value.trim().toLocaleLowerCase();return accountChats.value.filter(conversation=>!term||channelConversationName(conversation).toLocaleLowerCase().includes(term)||String(conversation.display?.preview??conversation.lastMessage??'').toLocaleLowerCase().includes(term))})
const recordConversation=computed<Conversation|undefined>(()=>accountRecordConversation(props.state.conversations,selectedAccountId.value,recordId.value))
const recordMessages=computed(()=>recordConversation.value?props.state.messages.filter(message=>message.conversationId===recordConversation.value!.id):[])
const shownCount=computed(()=>accountChats.value.filter(conversation=>(conversation as Conversation&{showInMainList?:boolean}).showInMainList===true).length)
function shownInMain(conversation:Conversation){if(Object.hasOwn(props.displayDrafts,conversation.id))return props.displayDrafts[conversation.id];return (conversation as Conversation&{showInMainList?:boolean}).showInMainList===true}
function accountName(account:any){return channelAccountName({...account,platform:plugins.value.find(plugin=>plugin.id===account.pluginId)?.platform??account.platform})}
function platformIcon(platform?:string){return ['qq','qq-openid'].includes(platform??'')?'brand:qq':['wechat','weixin','weixin-ilink'].includes(platform??'')?'brand:wechat':'channels'}
function selectAccount(id:string){rememberAccountScroll();cancelPendingTarget();selectedAccountId.value=id;recordId.value='';recordSearch.value='';void nextTick(()=>{restoreAccountScroll();detail.value?.focus({preventScroll:true})})}
function showRecords(conversation:Conversation){cancelPendingTarget();if(!accountRecordConversation(props.state.conversations,selectedAccountId.value,conversation.id))return;rememberAccountScroll();recordId.value=conversation.id;void nextTick(()=>detail.value?.focus({preventScroll:true}))}
function closeRecords(){const id=recordId.value;recordId.value='';void nextTick(()=>{restoreAccountScroll();detail.value?.querySelector<HTMLButtonElement>(`[data-record-id="${CSS.escape(id)}"]`)?.focus({preventScroll:true})})}
let targetPending=true,targetReadRevision=0,disposed=false
const targetStatus=ref<{kind:'waiting'|'error';message:string}|null>(null),targetReloading=ref(false)
function cancelPendingTarget(){targetPending=false;targetReadRevision++;targetStatus.value=null;targetReloading.value=false}
function targetMessage(reason:string){return ({'account-required':'缺少频道账号，无法打开会话记录。','account-missing':'频道账号不存在或已移除，请重新读取。','account-mismatch':'此会话不属于指定频道账号，请重新读取。','conversation-missing':'未找到会话记录，可重新读取。'} as Record<string,string>)[reason]??'无法打开会话记录，请重新读取。'}
function applyTarget(){
 // A section-only navigation is not an unresolved account/record destination.
 if(!props.target?.accountId&&!props.target?.conversationId){cancelPendingTarget();return}
 if(!targetPending)return
 const result=resolveAccountRecordTarget(props.state.conversations,connections.value,props.target)
 if(result.status==='ready'){
  rememberAccountScroll();selectedAccountId.value=result.accountId!;recordId.value=result.conversationId!;targetPending=false;targetStatus.value=null
 }else if(result.status==='error'){
  targetPending=result.pending;recordId.value='';targetStatus.value={kind:'error',message:targetMessage(result.reason!)}
 }else{
  // Keep a confirmed missing-record error visible until a retry or real data
  // resolves it; periodic account reads must not erase the recovery action.
  if(props.target.conversationId!==recordId.value)recordId.value='';if(targetStatus.value?.kind!=='error')targetStatus.value={kind:'waiting',message:props.target.conversationId?'正在读取会话记录…':'正在读取频道账号…'}
 }
}
async function retryTarget(){
 if(!props.target||targetReloading.value)return
 const revision=++targetReadRevision,target={...props.target};targetPending=true;targetReloading.value=true;targetStatus.value={kind:'waiting',message:'正在重新读取…'}
 try{
  // Only an explicit fresh read can establish that a validated target vanished;
  // no timeout or initially incomplete parent snapshot is treated as absence.
  const [snapshot]=await Promise.all([request<Snapshot>('/snapshot'),load()])
  if(disposed||revision!==targetReadRevision)return
  const result=resolveAccountRecordTarget(snapshot.conversations,connections.value,target,{fresh:true})
  if(result.status==='error'){targetPending=result.pending;targetStatus.value={kind:'error',message:targetMessage(result.reason!)}}
  else{targetPending=true;targetStatus.value={kind:'waiting',message:'正在读取会话记录…'};emit('refresh');if(resolveAccountRecordTarget(props.state.conversations,connections.value,target).status==='ready')applyTarget()}
 }catch(cause){if(disposed||revision!==targetReadRevision)return;targetPending=true;targetStatus.value={kind:'error',message:cause instanceof Error?cause.message:'读取失败，请重试。'}}
 finally{if(revision===targetReadRevision)targetReloading.value=false}
}
watch(()=>props.target,()=>{targetReadRevision++;targetReloading.value=false;targetPending=true;targetStatus.value=null;applyTarget()},{deep:true})
watch(()=>props.state.conversations,()=>{applyTarget();if(recordId.value&&!recordConversation.value)recordId.value=''})
const plugins=ref<any[]>([]),connections=ref<any[]>([]),file=ref<HTMLInputElement>(),busy=ref(''),dialog=ref(false),pluginId=ref(''),accountId=ref(''),characterId=ref(''),config=ref<Record<string,string>>({}),qr=ref<any>(),qrOpen=ref(false),qrImage=ref(''),qrAccount=ref(''),loaded=ref(false),removeOpen=ref(false),removeId=ref('')
let poll:ReturnType<typeof setInterval>|undefined
const selected=computed(()=>plugins.value.find(p=>p.id===pluginId.value)),statuses:Record<string,string>={disconnected:'未连接',connecting:'连接中',connected:'已连接','waiting-webhook':'等待事件','waiting-login':'等待登录',reconnecting:'重新连接中','login-expired':'登录已过期',error:'连接异常'}
let loadingAccounts=false,refreshQueued=false
async function load(){if(disposed)return;if(import.meta.env.DEV&&new URLSearchParams(location.search).has('preview'))return;if(loadingAccounts){refreshQueued=true;return}loadingAccounts=true;accountsLoading.value=!loaded.value;try{const r=await request('/channels');plugins.value=r.plugins??[];connections.value=r.connections??[];loaded.value=true;accountError.value='';if(!connections.value.some(account=>account.accountId===selectedAccountId.value)){selectedAccountId.value=connections.value[0]?.accountId??'';recordId.value=''}applyTarget()}catch(e){accountError.value=e instanceof Error?e.message:String(e);emit('error',e)}finally{loadingAccounts=false;accountsLoading.value=false;if(refreshQueued){refreshQueued=false;if(props.active)void load()}}}
watch(()=>props.refreshKey,()=>{if(props.active)void load()})
watch(()=>props.active,v=>{clearInterval(poll);if(v){void load();poll=setInterval(load,5000)}},{immediate:true});onBeforeUnmount(()=>{disposed=true;targetReadRevision++;refreshQueued=false;clearInterval(poll)})
function configure(plugin:any,account?:any){if(!plugin)return;pluginId.value=plugin.id;accountId.value=account?.accountId??'';characterId.value=account?.characterId??props.state.characters[0]?.id??'';config.value=Object.fromEntries(Object.entries(plugin.configSchema??{}).map(([k,s]:any)=>[k,account?.config?.[k]??s.default??'']));dialog.value=true}
async function install(e:Event){const input=e.target as HTMLInputElement,f=input.files?.[0];if(!f)return;busy.value='import';try{await upload('/channels/import',f);await load();emit('notice','渠道插件已安装')}catch(e){emit('error',e)}finally{busy.value='';input.value=''}}
async function save(){if(busy.value||!characterId.value)return;busy.value='save';try{const payload={pluginId:pluginId.value,characterId:characterId.value,config:Object.fromEntries(Object.entries(config.value).filter(([k,v])=>selected.value?.configSchema?.[k]?.type!=='secret'||v))};if(accountId.value)await request(`/channels/accounts/${encodeURIComponent(accountId.value)}`,payload,'PATCH');else await request('/channels/accounts',payload);dialog.value=false;await load();emit('refresh');emit('notice','渠道配置已保存')}catch(e){emit('error',e)}finally{busy.value=''}}
async function command(account:string,action:string){busy.value=account;try{const result=await request(`/channels/accounts/${encodeURIComponent(account)}/${action}`,{});await load();emit('refresh');return result}catch(e){emit('error',e)}finally{busy.value=''}}
async function showQr(account:string){const result=await command(account,'qr');if(!result)return;qrAccount.value=account;qr.value=result;qrOpen.value=true;qrImage.value='';if(result.qrImage)qrImage.value=result.qrImage;else if(result.qrImageUrl)qrImage.value=result.qrImageUrl;else if(result.qrContent){const QRCode=await import('qrcode');qrImage.value=await QRCode.toDataURL(result.qrContent,{width:240,margin:2,color:{dark:'#222222',light:'#ffffff'}})}}
async function checkQr(){const result=await command(qrAccount.value,'poll');if(result){qr.value={...qr.value,...result};if(['confirmed','connected'].includes(result.status)){qrOpen.value=false;emit('notice',result.connectionStatus==='connected'?'账号已连接':'扫码已完成，账号正在连接')}}}
async function remove(){if(busy.value)return;busy.value='remove';try{await request(`/channels/accounts/${encodeURIComponent(removeId.value)}`,undefined,'DELETE');removeOpen.value=false;await load();emit('refresh')}catch(e){emit('error',e)}finally{busy.value=''}}
</script>
<template><section class="channels-page channel-manager business-page">
  <aside class="channel-accounts" aria-label="频道账号">
    <header class="channel-accounts-toolbar"><label class="channel-account-search"><Icon name="search" :size="16"/><input v-model="accountSearch" aria-label="搜索频道账号" placeholder="搜索账号"/></label><button class="icon-button" aria-label="导入渠道插件" :disabled="busy==='import'" @click="file?.click()"><Icon name="plus" :size="18"/></button></header>
    <input ref="file" hidden aria-hidden="true" tabindex="-1" type="file" accept=".zip" @change="install"/>
    <div ref="accountList" class="channel-account-list">
      <button v-for="account in visibleAccounts" :key="account.accountId" class="channel-account-choice" :aria-pressed="selectedAccountId===account.accountId" @click="selectAccount(account.accountId)"><Icon class="account-platform-icon" :name="platformIcon(plugins.find(plugin=>plugin.id===account.pluginId)?.platform??account.platform)" :size="32"/><span><strong>{{accountName(account)}}</strong><small>{{statuses[account.status]??account.status}}</small></span></button>
      <p v-if="accountsLoading" class="channel-empty" role="status">正在加载账号…</p><p v-else-if="!visibleAccounts.length" class="channel-empty">{{accountSearch?'没有匹配的账号':accountError?'账号加载失败':'暂无频道账号'}}</p><button v-if="accountError" class="button channel-account-retry" @click="load">重试</button>
    </div>
    <section class="channel-add-accounts" aria-label="添加账号"><h2>添加账号</h2><button v-for="plugin in plugins" :key="plugin.id" class="channel-plugin-choice" @click="configure(plugin)"><Icon :name="platformIcon(plugin.platform)" :size="22"/><span>{{plugin.name}}</span><Icon name="plus" :size="16"/></button><button v-if="!plugins.length&&!accountsLoading" class="text-button" :disabled="busy==='import'" @click="file?.click()"><Icon name="upload" :size="16"/>{{busy==='import'?'安装中…':'导入插件'}}</button></section>
  </aside>
  <section ref="detail" tabindex="-1" class="channel-account-detail" :aria-label="recordConversation?'频道会话记录':'频道账号详情'">
    <div v-if="targetStatus" class="channel-target-status" :class="{'is-error':targetStatus.kind==='error'}" :role="targetStatus.kind==='error'?'alert':'status'"><span>{{targetStatus.message}}</span><button class="text-button" :disabled="targetReloading" @click="retryTarget">{{targetReloading?'正在读取…':'重新读取'}}</button></div>
    <template v-if="selectedAccount">
      <template v-if="recordConversation"><header class="channel-record-header"><button class="text-button" @click="closeRecords"><Icon name="back" :size="16"/>返回账号</button><span><strong>{{channelConversationName(recordConversation)}}</strong><small>{{accountName(selectedAccount)}}</small></span><button class="button" @click="emit('open-conversation',recordConversation.id)">打开对话<Icon name="arrow" :size="16"/></button></header><MessageTimeline :messages="recordMessages" :conversation="recordConversation" :characters="state.characters" :active-runs="[]" :pending="[]" :active="active" :design-preview="false"><p v-if="!recordMessages.length" class="channel-empty">暂无消息记录</p></MessageTimeline></template>
      <div v-else ref="accountScroll" class="channel-account-scroll" @scroll="rememberAccountScroll">
        <header class="channel-account-title"><Icon :name="platformIcon(selectedPlugin?.platform??selectedAccount.platform)" :size="36"/><div><h1>{{accountName(selectedAccount)}}</h1><p><span class="status-dot" :class="{online:selectedAccount.status==='connected'}"/>{{statuses[selectedAccount.status]??selectedAccount.status}}</p></div><button class="icon-button" aria-label="编辑频道账号" :disabled="!selectedPlugin" @click="configure(selectedPlugin,selectedAccount)"><Icon name="settings" :size="18"/></button></header>
        <p v-if="selectedAccount.detail||selectedAccount.error" class="inline-error">{{typeof selectedAccount.detail==='string'?selectedAccount.detail:selectedAccount.error}}</p>
        <section class="channel-setting-group" aria-label="账号与身份"><h2>账号与身份</h2><div class="channel-setting-row"><span>渠道</span><span>{{channelPlatformName(selectedPlugin?.platform??selectedAccount.platform)}}</span></div><div class="channel-setting-row"><span>参与角色</span><span class="channel-role-name"><CharacterAvatar v-if="state.characters.find(person=>person.id===selectedAccount.characterId)" :person="state.characters.find(person=>person.id===selectedAccount.characterId)"/>{{state.characters.find(person=>person.id===selectedAccount.characterId)?.name??'未分配角色'}}</span></div><button class="channel-setting-row channel-plugin-link" @click="emit('open-plugin',selectedAccount.pluginId)"><span>连接插件</span><span>{{selectedPlugin?.name??selectedAccount.pluginId}}<Icon name="chevron" :size="16"/></span></button><div v-if="selectedAccount.webhookUrl" class="channel-setting-row webhook-row"><span>事件回调</span><code>{{selectedAccount.webhookUrl}}</code></div></section>
        <section class="channel-setting-group" aria-label="频道会话"><header class="channel-conversation-heading"><h2>会话</h2><span>已展示 {{shownCount}}/{{accountChats.length}}</span></header><label v-if="accountChats.length" class="channel-record-search"><Icon name="search" :size="16"/><input v-model="recordSearch" aria-label="搜索账号内会话" placeholder="搜索会话"/></label><p v-if="!displaySupported&&accountChats.length" class="channel-compatibility" role="status">当前服务不支持调整主列表展示。</p><article v-for="conversation in visibleChats" :key="conversation.id" class="channel-conversation-setting"><ChannelConversationAvatar :conversation="conversation"/><div class="channel-conversation-copy"><strong>{{channelConversationName(conversation)}}</strong><small>{{conversation.kind==='group'?'群聊':'单聊'}} · {{conversation.display?.preview??conversation.lastMessage??'暂无消息'}}</small><div class="channel-conversation-actions"><button :data-record-id="conversation.id" class="text-button" @click="showRecords(conversation)">查看记录</button><button class="text-button" @click="emit('open-conversation',conversation.id)">打开对话<Icon name="arrow" :size="14"/></button></div><p v-if="displayErrors[conversation.id]" class="inline-error channel-display-error" role="alert"><span>{{displayErrors[conversation.id]}}</span><button class="text-button" :disabled="!displaySupported||displayBusyIds.includes(conversation.id)" @click="emit('display',conversation.id,shownInMain(conversation))">重试保存</button></p></div><ToggleSwitch :model-value="shownInMain(conversation)" :disabled="!displaySupported||displayBusyIds.includes(conversation.id)" :aria-label="`在主列表展示：${channelConversationName(conversation)}`" @update:model-value="emit('display',conversation.id,$event)"/></article><p v-if="!visibleChats.length" class="channel-empty">{{recordSearch?'没有匹配的会话':'暂无频道会话'}}</p></section>
        <section class="channel-setting-group channel-account-operations" aria-label="账号操作"><h2>连接</h2><div class="channel-setting-row"><span>账号连接</span><button class="button" :disabled="Boolean(busy)" @click="command(selectedAccount.accountId,selectedAccount.status==='connected'?'disconnect':'connect')"><Icon :name="selectedAccount.status==='connected'?'disconnect':'plug'" :size="16"/>{{busy===selectedAccount.accountId?'请稍候…':selectedAccount.status==='connected'?'断开连接':'连接'}}</button></div><div v-if="selectedPlugin?.capabilities?.includes('login-qr')" class="channel-setting-row"><span>扫码登录</span><button class="button" :disabled="Boolean(busy)" @click="showQr(selectedAccount.accountId)"><Icon name="qr" :size="16"/>扫码登录</button></div><div class="channel-setting-row"><span>移除账号</span><button class="text-button subtle" :disabled="Boolean(busy)" @click="removeId=selectedAccount.accountId;removeOpen=true"><Icon name="delete" :size="16"/>移除</button></div></section>
      </div>
    </template><div v-else class="channel-empty channel-no-account"><Icon name="channels" :size="32"/><p>{{accountsLoading?'正在加载账号…':'选择频道账号'}}</p></div>
  </section>
<Modal :open="dialog" :title="accountId?'编辑渠道':'连接渠道账号'" @close="!busy&&(dialog=false)"><form @submit.prevent="save"><p class="dialog-description">{{selected?.name}}</p><label class="field">绑定角色<CustomSelect v-model="characterId" aria-label="绑定角色" :disabled="Boolean(busy)" :options="state.characters.map(person=>({value:person.id,label:person.name}))"/></label><label v-for="(schema,key) in selected?.configSchema" :key="key" class="field">{{schema.label}}<input v-model="config[key]" :disabled="Boolean(busy)" :type="schema.type==='secret'?'password':'text'" :autocomplete="schema.type==='secret'?'new-password':'off'" :required="schema.required&&(!accountId||schema.type!=='secret')" :placeholder="schema.type==='secret'&&accountId?'留空保留已保存的值':schema.default??''"/></label><footer class="form-footer"><button class="button primary" :disabled="Boolean(busy)||!characterId"><Icon name="save" :size="16"/>{{busy==='save'?'保存中…':'保存配置'}}</button></footer></form></Modal>
<Modal :open="qrOpen" title="扫码连接" @close="qrOpen=false"><div class="qr-content"><img v-if="qrImage" :src="qrImage" width="240" height="240" alt="账号登录二维码"/><p>{{qr?.message??'请使用对应的手机应用扫描二维码，并确认登录。'}}</p><p v-if="qr?.status" class="muted">{{({wait:'等待扫码',scaned:'已扫码，等待确认',expired:'二维码已过期',need_verifycode:'请在手机上完成验证'} as Record<string,string>)[qr.status]??qr.status}}</p><div class="button-row"><button class="button" :disabled="Boolean(busy)" @click="showQr(qrAccount)"><Icon name="refresh" :size="16"/>刷新二维码</button><button class="button primary" :disabled="Boolean(busy)" @click="checkQr"><Icon name="check" :size="16"/>我已确认登录</button></div></div></Modal>
<Modal :open="removeOpen" title="移除这个账号？" @close="!busy&&(removeOpen=false)"><p>账号会断开连接并移除本地配置，已有对话仍会保留。</p><footer class="form-footer"><button class="button" :disabled="Boolean(busy)" @click="removeOpen=false">保留</button><button class="button danger" :disabled="Boolean(busy)" @click="remove"><Icon name="delete" :size="16"/>移除账号</button></footer></Modal></section></template>
<style src="../business-components.css"></style>
<style scoped>
.channel-manager{display:flex;flex-direction:row;width:100%;height:100%;min-width:0;min-height:0;overflow:hidden;background:var(--sand-bg-pane)}
.channel-accounts{display:flex;flex-direction:column;flex:0 0 216px;width:216px;min-width:0;min-height:0;border-right:.5px solid var(--sand-border-primary-translucent);background:var(--sand-bg-sidebar)}
.channel-accounts-toolbar{display:flex;align-items:center;gap:8px;padding:16px 8px 8px;flex:none}
.channel-account-search,.channel-record-search{display:flex;align-items:center;gap:8px;min-width:0;height:28px;padding:4px 8px;background:var(--sand-bg-secondary);border-radius:10px;color:var(--sand-icon-secondary)}
.channel-account-search{flex:1}.channel-account-search input,.channel-record-search input{width:100%;min-width:0;border:0;padding:0;background:transparent;color:var(--sand-text-primary);font-size:13px;line-height:18px}
.channel-account-list{flex:1;min-height:0;overflow:auto;padding:0 8px;overscroll-behavior:contain}
.channel-account-choice{display:flex;align-items:center;gap:8px;width:100%;min-width:0;padding:8px 8px;border-radius:10px;text-align:left}
.channel-account-choice:hover,.channel-plugin-choice:hover{background:var(--sand-bg-hover)}.channel-account-choice[aria-pressed=true]{background:var(--sand-bg-active)}
.channel-account-choice>span{display:flex;flex-direction:column;min-width:0;gap:4px}.channel-account-choice strong{font-size:14px;line-height:20px;font-weight:500;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.channel-account-choice small{font-size:12px;line-height:16px;color:var(--sand-text-secondary)}.account-platform-icon{flex:none}
.channel-add-accounts{padding:16px 12px;flex:none;max-height:40%;overflow:auto}.channel-add-accounts h2,.channel-setting-group h2{margin:0;font-size:12px;line-height:16px;font-weight:500;color:var(--sand-text-secondary)}.channel-add-accounts h2{margin:0 8px 8px}
.channel-plugin-choice{display:flex;align-items:center;gap:8px;width:100%;min-height:36px;padding:4px;border-radius:6px;font-size:13px;line-height:18px;text-align:left}.channel-plugin-choice>span{flex:1;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.channel-account-retry{margin:0 12px}
